#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\ndocker build -t survival-quote-test . > /dev/null\n\n# Run the container with a known QUOTE_INDEX\nCONTAINER_ID=$(docker run -d -e QUOTE_INDEX=1 -p 5001:5000 survival-quote-test)\n# Give the service a moment to start\nsleep 2\n# Fetch the quote\nRESPONSE=$(curl -s http://localhost:5001/quote)\n# Expected deterministic output\nEXPECTED='{"quote":"Keep your wits sharp and your water bottle fuller."}'\nif [ "$RESPONSE" != "$EXPECTED" ]; then\n  echo "Test failed: expected $EXPECTED but got $RESPONSE"\n  docker rm -f $CONTAINER_ID > /dev/null\n  exit 1\nfi\n# Clean up\ndocker rm -f $CONTAINER_ID > /dev/null\necho "Test passed"
